{
  "items": [
    {
      "title": "Regional Data (Federal States), Germany, 1960–1970",
      "url_or_doi": "https://doi.org/10.4232/1.0920",
      "justification": "A GESIS dataset covering German federal states between 1960 and 1970. Includes regional statistics relevant to population, employment, education, housing environments, urban and rural communities, transportation, economic conditions, and public services. Particularly useful for examining regional differences in community life and socioeconomic development during the 1960s."
    },
    {
      "title": "District Database (Kreisdatenbank), West Germany, 1939–1975",
      "url_or_doi": "https://doi.org/10.4232/1.1212",
      "justification": "Contains 219 variables describing 542 administrative districts in West Germany, including West Berlin. Provides structural characteristics of districts and socioeconomic indicators for selected years between 1939 and 1975. Particularly relevant for comparing urban and rural districts and investigating regional inequalities during the 1960s."
    },
    {
      "title": "Urban Planning Data Collection (Städtebauliche Datenerfassung), 1968",
      "url_or_doi": "https://doi.org/10.4232/1.0488",
      "justification": "A GESIS survey dataset from 1968 examining residential environments and everyday urban life. Covers neighborhood relationships, housing satisfaction, dwelling characteristics, heating systems, housing costs, accessibility of local facilities, and participation in cultural activities. Especially valuable for investigating community relationships, living conditions, and experiences of urban environments in late-1960s Germany."
    },
    {
      "title": "Structural Survey in the District of Eschwege (Population), 1965",
      "url_or_doi": "https://doi.org/10.4232/1.0081",
      "justification": "A historical GESIS dataset collected in 1965 focusing on the population of the Eschwege district in West Germany. Provides a geographically specific source for investigating demographic and community structures in a predominantly small-town and rural district during the 1960s. Useful for localized research and comparisons with larger urban regions."
    },
    {
      "title": "Regional Data from the 1961 Census (Administrative Regions)",
      "url_or_doi": "https://search.gesis.org/research_data/ZA1828",
      "justification": "Contains regional statistics derived from the 1961 West German population census. Includes geographical area and population indicators, with historical population comparisons. Useful for establishing demographic conditions at the beginning of the 1960s and examining differences between administrative regions with varying degrees of urbanization."
    },
    {
      "title": "Regional Data from the 1970 Census (Federal States)",
      "url_or_doi": "https://doi.org/10.4232/1.1740",
      "justification": "A comprehensive GESIS dataset containing demographic and socioeconomic indicators from the 1970 West German census, including historical population figures for 1961. Covers age, marital status, religion, household composition, migration, education, employment, commuting, agricultural enterprises, and agricultural land. Highly relevant for studying the transformation of urban and rural communities throughout the 1960s."
    },
    {
      "title": "Population and Municipalities by Municipality Size Classes in Germany, 1871–2010",
      "url_or_doi": "https://doi.org/10.4232/1.11731",
      "justification": "A historical statistical compilation documenting changes in population and the number of municipalities across different municipality-size categories in Germany. Includes the 1960s within its historical coverage. Particularly useful for examining urbanization, rural population patterns, settlement structures, and the changing distribution of Germans between small communities and larger cities."
    },
    {
      "title": "Residential Buildings, Dwellings, Households and Population per Dwelling in North Rhine-Westphalia, 1885–1968",
      "url_or_doi": "https://doi.org/10.4232/1.13189",
      "justification": "A historical housing dataset covering the territory of present-day North Rhine-Westphalia through 1968. Contains statistics concerning residential buildings, dwellings, households, and population per dwelling. Useful for studying housing conditions, residential density, household structures, and long-term urban development in one of Germany's most industrialized regions during the 1960s."
    },
    {
      "title": "Selected Data on Residential Housing Supply in Germany, 1918–1965",
      "url_or_doi": "https://doi.org/10.4232/1.10288",
      "justification": "A GESIS historical data compilation documenting housing supply in Germany between 1918 and 1965. Relevant to research on postwar reconstruction, housing availability, residential conditions, and urbanization during the early and middle 1960s. Provides historical context for understanding how housing development influenced everyday community life."
    },
    {
      "title": "German Microcensus Trendfile, 1962–2016",
      "url_or_doi": "https://www.gesis.org/en/gml/microcensus/microcensus-trendfile",
      "justification": "A harmonized collection of German Microcensus data covering more than five decades, including annual survey files from 1962 through 1969. Contains more than 160 harmonized variables covering multiple dimensions of demographic and social change in West Germany. Particularly valuable for studying household composition, employment, family structures, and social differences during the 1960s. Researchers can use the historical microdata to investigate patterns of everyday life and social transformation."
    },
    {
      "title": "The German Local Population Database (GPOP), 1871–2019",
      "url_or_doi": "https://doi.org/10.1515/jbnst-2022-0046",
      "justification": "A historical database documenting population development across German municipalities using harmonized geographical boundaries. Includes census observations from 1961 in West Germany and 1964 in East Germany. Especially useful for examining population distribution, urban growth, rural depopulation, and geographical differences between East and West Germany during the 1960s. The linked research article provides information about the dataset and its availability."
    },
    {
      "title": "Resident Population of the German Democratic Republic, 1969–1989",
      "url_or_doi": "https://doi.org/10.7802/1454",
      "justification": "A historical population dataset covering East Germany from 1969 onward. Provides total, male, and female resident population figures at district, regional, and national levels, based on official East German statistical yearbooks. The 1969 observations are particularly useful for examining the demographic structure of East German communities at the end of the 1960s and comparing urban and rural population distributions."
    },
    {
      "title": "Historical GIS Datafiles: Federal Republic of Germany and German Democratic Republic, 1949–1989",
      "url_or_doi": "https://mosaic.ipums.org/historical-gis-datafiles",
      "justification": "A historical geographical dataset from the Max Planck Institute for Demographic Research's Population History GIS Collection, distributed through Census Mosaic. Provides annual administrative district boundaries for both West and East Germany from 1949 to 1989. Particularly valuable for mapping urban and rural communities during the 1960s, identifying historical district boundaries, and linking population or socioeconomic statistics to geographical locations."
    },
    {
      "title": "Group-Specific Residential Behavior (Gruppenspezifisches Wohnverhalten), 1970",
      "url_or_doi": "https://doi.org/10.4232/1.1169",
      "justification": "A GESIS dataset collected in June 1970 focusing on residents of the Hustadt housing development who had moved there by summer 1969. Although collected just after the 1960s, it provides evidence about residents of a newly developed community established during that decade. Useful for investigating residential behavior, housing preferences, and social life in modern West German housing developments."
    },
    {
      "title": "Building Forms and Residential Behavior (Bauform und Wohnverhalten), 1970",
      "url_or_doi": "https://doi.org/10.4232/1.0526",
      "justification": "A GESIS residential study conducted in September and October 1970, examining housing forms and residential behavior in the Hamburg-Eidelstedt area. Although the survey dates fall just outside the requested decade, it offers relevant evidence about community and housing developments associated with late-1960s urban planning. Useful for studying residential environments and everyday life in social housing communities."
    }
  ]
}
